'use strict';
/*
 * Mock "MediSoft HIS" - simulates a partnered hospital-software vendor.
 *  - OAuth 2.0 authorization-code flow with PKCE S256 required: /oauth/authorize (login + consent), /oauth/token, /oauth/revoke
 *  - Read-only APIs: GET /api/stock (scope stock.read), GET /api/schedule (scope schedule.read)
 * Patient MRNs exist only inside this "HIS"; /api/schedule returns SHA-256(salt:mrn) - hashing at source.
 * All data is SYNTHETIC (generated by ../seed/generate.js).
 */
const path = require('path');
const PLATFORM_PORT = process.env.PORT; // read before dotenv: backend/.env's PORT is CAP's (4004), not ours
require('dotenv').config({ path: path.join(__dirname, '..', 'backend', '.env'), quiet: true });
const express = require('express');
const crypto = require('crypto');
const fs = require('fs');

const SCOPES = {
  'stock.read': 'Stock and batch details: drug, brand, manufacturer, batch, expiry, storage, seal status',
  'schedule.read': 'Chemo schedule: dates, doses and treatment intent. Patient IDs are hashed; no names are shared',
};

function loadSeed() {
  const file = path.join(__dirname, 'data', 'seed.json');
  try {
    const gen = require('../seed/generate');
    if (process.env.SEED_AUTO_REFRESH !== 'false' && (gen.isStale() || !fs.existsSync(file))) gen.run({ quiet: true });
  } catch { /* seed generator not available: use existing file */ }
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function createApp(opts = {}) {
  const env = { ...process.env, ...(opts.env || {}) };
  const clientId = env.MEDISOFT_OAUTH_CLIENT_ID || 'medilink-client';
  const clientSecret = env.MEDISOFT_OAUTH_CLIENT_SECRET || 'dev-medisoft-secret';
  const redirectUris = String(env.MEDISOFT_ALLOWED_REDIRECTS || env.MEDISOFT_OAUTH_REDIRECT_URI || 'http://localhost:4004/oauth/medisoft/callback').split(',').map(s => s.trim());
  const salt = env.PATIENT_REF_HASH_SALT || 'dev-patient-salt';
  const seed = opts.seed || loadSeed();
  const sessions = new Map(), codes = new Map(), access = new Map(), refresh = new Map();
  const rand = (n = 24) => crypto.randomBytes(n).toString('hex');
  const hashRef = mrn => crypto.createHash('sha256').update(`${salt}:${mrn}`).digest('hex');
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const page = (title, body) => `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>body{font-family:system-ui,sans-serif;background:#eef3f7;margin:0}main{max-width:26rem;margin:3rem auto;background:#fff;border-radius:12px;padding:2rem;box-shadow:0 2px 12px #0002}h1{font-size:1.2rem;color:#0a4d8c}label{display:block;margin:.8rem 0 .2rem}input{width:100%;padding:.6rem;box-sizing:border-box}button{padding:.7rem 1.2rem;margin:1rem .5rem 0 0;border:0;border-radius:6px;font-size:1rem}.allow{background:#0a6ed1;color:#fff}.deny{background:#ddd}li{margin:.4rem 0}small{color:#666}</style></head><body><main><div><b>MediSoft HIS</b> <small>(mock, synthetic data)</small></div>${body}</main></body></html>`;
  const AUTH_PARAMS = ['response_type', 'client_id', 'redirect_uri', 'scope', 'state', 'code_challenge', 'code_challenge_method'];
  const hidden = q => AUTH_PARAMS.map(k => `<input type="hidden" name="${k}" value="${esc(q[k])}">`).join('');
  const cookieSid = req => (/(?:^|;\s*)msid=([a-f0-9]+)/.exec(req.headers.cookie || '') || [])[1];
  function validAuthorizeParams(q) {
    if (q.response_type !== 'code') return 'unsupported_response_type';
    if (q.client_id !== clientId) return 'unauthorized_client';
    if (!redirectUris.includes(q.redirect_uri)) return 'invalid_redirect_uri';
    const scopes = String(q.scope || '').split(/\s+/).filter(Boolean);
    if (!scopes.length || scopes.some(s => !SCOPES[s])) return 'invalid_scope';
    if (q.code_challenge_method !== 'S256' || !/^[A-Za-z0-9_-]{43,128}$/.test(q.code_challenge || '')) return 'invalid_request: PKCE S256 code_challenge required';
    return null;
  }
  function clientAuth(req) {
    const m = /^Basic (.+)$/.exec(req.headers.authorization || '');
    let id = req.body.client_id, secret = req.body.client_secret;
    if (m) [id, secret] = Buffer.from(m[1], 'base64').toString().split(':');
    const ok = id === clientId && secret && crypto.timingSafeEqual(Buffer.from(String(secret).padEnd(64)), Buffer.from(clientSecret.padEnd(64)));
    return ok;
  }
  function issue(grant) {
    const at = rand(), rt = rand();
    access.set(at, { ...grant, exp: Date.now() + 3600 * 1000 });
    refresh.set(rt, grant);
    return { access_token: at, token_type: 'Bearer', expires_in: 3600, refresh_token: rt, scope: grant.scope, tenant: grant.tenant };
  }
  function bearer(scope) {
    return (req, res, next) => {
      const m = /^Bearer (\S+)$/.exec(req.headers.authorization || '');
      const g = m && access.get(m[1]);
      if (!g || g.exp < Date.now()) return res.status(401).json({ error: 'invalid_token' });
      if (!g.scope.split(' ').includes(scope)) return res.status(403).json({ error: 'insufficient_scope', scope });
      req.grant = g; next();
    };
  }

  const app = express();
  app.use(express.urlencoded({ extended: false }));
  app.use(express.json());
  app.get('/health', (_, res) => res.json({ status: 'UP', tenants: Object.keys(seed.tenants), anchor: seed.anchor }));

  app.get('/oauth/authorize', (req, res) => {
    const e = validAuthorizeParams(req.query);
    if (e) return res.status(400).send(page('Error', `<h1>Request refused</h1><p>${esc(e)}</p>`));
    const user = sessions.get(cookieSid(req));
    if (!user) {
      return res.send(page('Sign in', `<h1>Sign in to MediSoft</h1><form method="post" action="/oauth/login">${hidden(req.query)}<label>Username</label><input name="username" autocomplete="username"><label>Password</label><input name="password" type="password" autocomplete="current-password"><button class="allow">Sign in</button></form><p><small>Demo users: pharm.jayanagar / pharm.banashankari, password medisoft-demo</small></p>`));
    }
    const scopes = String(req.query.scope).split(/\s+/);
    res.send(page('Allow access', `<h1>Allow <b>MediLink</b> to read from ${esc(seed.tenants[user.tenant]?.hospitalId)}?</h1><p>Signed in as ${esc(user.displayName)}</p><p>MediLink will get <b>read-only</b> access to:</p><ul>${scopes.map(s => `<li>${esc(SCOPES[s])}</li>`).join('')}</ul><p><small>MediLink cannot change anything in MediSoft. You can disconnect at any time.</small></p><form method="post" action="/oauth/consent">${hidden(req.query)}<button class="allow" name="decision" value="allow">Allow</button><button class="deny" name="decision" value="deny">Deny</button></form>`));
  });

  app.post('/oauth/login', (req, res) => {
    const u = seed.users.find(x => x.username === req.body.username && x.password === req.body.password);
    const q = new URLSearchParams(Object.fromEntries(AUTH_PARAMS.map(k => [k, req.body[k] || ''])));
    if (!u) return res.status(401).send(page('Sign in', `<h1>Wrong username or password</h1><p><a href="/oauth/authorize?${esc(q)}">Try again</a></p>`));
    const sid = rand(16);
    sessions.set(sid, u);
    res.setHeader('Set-Cookie', `msid=${sid}; HttpOnly; SameSite=Lax; Path=/`);
    res.redirect(302, `/oauth/authorize?${q}`);
  });

  app.post('/oauth/consent', (req, res) => {
    const user = sessions.get(cookieSid(req));
    const e = validAuthorizeParams(req.body);
    if (!user || e) return res.status(400).send(page('Error', `<h1>Request refused</h1><p>${esc(e || 'not signed in')}</p>`));
    const target = new URL(req.body.redirect_uri);
    if (req.body.state) target.searchParams.set('state', req.body.state);
    if (req.body.decision !== 'allow') { target.searchParams.set('error', 'access_denied'); return res.redirect(302, target.toString()); }
    const code = rand(16);
    codes.set(code, { clientId, redirectUri: req.body.redirect_uri, scope: req.body.scope, challenge: req.body.code_challenge, tenant: user.tenant, user: user.username, exp: Date.now() + 60000 });
    target.searchParams.set('code', code);
    res.redirect(302, target.toString());
  });

  app.post('/oauth/token', (req, res) => {
    if (!clientAuth(req)) return res.status(401).json({ error: 'invalid_client' });
    if (req.body.grant_type === 'authorization_code') {
      const c = codes.get(req.body.code);
      codes.delete(req.body.code); // single use
      const s256 = crypto.createHash('sha256').update(String(req.body.code_verifier || '')).digest('base64url');
      if (!c || c.exp < Date.now() || c.redirectUri !== req.body.redirect_uri || s256 !== c.challenge) return res.status(400).json({ error: 'invalid_grant' });
      return res.json(issue({ scope: c.scope, tenant: c.tenant, user: c.user }));
    }
    if (req.body.grant_type === 'refresh_token') {
      const g = refresh.get(req.body.refresh_token);
      if (!g) return res.status(400).json({ error: 'invalid_grant' });
      refresh.delete(req.body.refresh_token); // rotate
      return res.json(issue(g));
    }
    res.status(400).json({ error: 'unsupported_grant_type' });
  });

  app.post('/oauth/revoke', (req, res) => {
    if (!clientAuth(req)) return res.status(401).json({ error: 'invalid_client' });
    const t = req.body.token;
    const g = access.get(t) || refresh.get(t);
    if (g) for (const m of [access, refresh]) for (const [k, v] of m) if (v.tenant === g.tenant && v.user === g.user) m.delete(k);
    res.status(200).json({ revoked: !!g });
  });

  const stock = (req, res) => {
    const t = seed.tenants[req.grant.tenant];
    res.json({ tenant: t.hospitalId, licenceNo: t.licenceNo, generatedAt: new Date().toISOString(), items: t.stock });
  };
  const schedule = (req, res) => {
    const t = seed.tenants[req.grant.tenant];
    const items = t.schedule.map(({ mrn, ...b }) => ({ ...b, patientRef: hashRef(mrn) })); // raw MRN never leaves the HIS
    res.json({ tenant: t.hospitalId, generatedAt: new Date().toISOString(), items });
  };
  // Read-only APIs; /stock and /schedule are aliases of the /api/* paths.
  for (const p of ['/api/stock', '/stock']) app.get(p, bearer('stock.read'), stock);
  for (const p of ['/api/schedule', '/schedule']) app.get(p, bearer('schedule.read'), schedule);
  app._state = { sessions, codes, access, refresh };
  return app;
}

if (require.main === module) {
  const port = Number(process.env.MEDISOFT_PORT || PLATFORM_PORT || new URL(process.env.MEDISOFT_BASE_URL || 'http://localhost:4100').port || 4100);
  createApp().listen(port, () => console.log(`[mock-medisoft] listening on http://localhost:${port} (synthetic data)`));
}
module.exports = { createApp };
